-- Name: actualizar_precio_modelo(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.actualizar_precio_modelo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    cantidadL NUMERIC;
    lineaID TEXT;
BEGIN
    UPDATE public."Linea de pedido" l
    SET "PrecioTotal" = l.cantidad * NEW.precio
    FROM public."Pedido" p
    WHERE p."id_linea_Linea de pedido" = l.id_linea
      AND p."id_modelo_Modelo" = NEW.id_modelo;

    RETURN NEW;
END;
$$;


