-- Name: comprobar_estadopedido(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comprobar_estadopedido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado NOT IN (
        'Entregado',
        'Enviado',
        'Pendiente',
        'En preparacion',
        'Cancelado'
    ) THEN
        RAISE EXCEPTION
        'El estado del pedido no es válido';
    END IF;

    RETURN NEW;
END;
$$;


