--

CREATE FUNCTION public.comprobar_modelo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.precio <= 0 THEN
        RAISE EXCEPTION
        'El precio del modelo debe ser mayor que 0';
    END IF;

    IF NEW.stock <= 0 THEN
        RAISE EXCEPTION
        'El stock del modelo debe ser mayor que 0';
    END IF;

    RETURN NEW;
END;
$$;


