--
-- TOC entry 249 (class 1255 OID 19148)
-- Name: comprobarstock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comprobarstock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    cantidadAnterior NUMERIC;
    cantidadNueva NUMERIC;
BEGIN

    IF TG_OP = 'UPDATE' THEN
        IF OLD.estado <> 'Cancelado' THEN

            SELECT cantidad
            INTO cantidadAnterior
            FROM public."Linea de pedido"
            WHERE id_linea = OLD."id_linea_Linea de pedido";

            UPDATE public."Modelo"
            SET stock = stock + cantidadAnterior
            WHERE id_modelo = OLD."id_modelo_Modelo";

        END IF;
    END IF;

    IF NEW.estado <> 'Cancelado' THEN

        SELECT cantidad
        INTO cantidadNueva
        FROM public."Linea de pedido"
        WHERE id_linea = NEW."id_linea_Linea de pedido";

        UPDATE public."Modelo"
        SET stock = stock - cantidadNueva
        WHERE id_modelo = NEW."id_modelo_Modelo"
          AND stock >= cantidadNueva;

        IF NOT FOUND THEN
            RAISE EXCEPTION
            'No hay existencias suficientes para realizar el pedido';
        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.comprobarstock() OWNER TO postgres;

--
-- TOC entry 250 (class 1255 OID 19150)
-- Name: comprobarstockcantidad(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comprobarstockcantidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    modeloID TEXT;
    estadoPedido TEXT;
    diferencia NUMERIC;
BEGIN

    SELECT p."id_modelo_Modelo", p.estado
    INTO modeloID, estadoPedido
    FROM public."Pedido" p
    WHERE p."id_linea_Linea de pedido" = NEW.id_linea
    LIMIT 1;

    IF NOT FOUND OR estadoPedido = 'Cancelado' THEN
        RETURN NEW;
    END IF;

    diferencia := NEW.cantidad - OLD.cantidad;

    IF diferencia > 0 THEN

        UPDATE public."Modelo"
        SET stock = stock - diferencia
        WHERE id_modelo = modeloID
          AND stock >= diferencia;

        IF NOT FOUND THEN
            RAISE EXCEPTION
            'Stock insuficiente';
        END IF;

    ELSIF diferencia < 0 THEN

        UPDATE public."Modelo"
        SET stock = stock + ABS(diferencia)
        WHERE id_modelo = modeloID;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.comprobarstockcantidad() OWNER TO postgres;

