CREATE FUNCTION public.impedir_cambioid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'Clientes'
       AND NEW.id_cliente <> OLD.id_cliente THEN
        RAISE EXCEPTION 'No se puede modificar id_cliente';
		
    ELSIF TG_TABLE_NAME = 'Productos'
       AND NEW.id_producto <> OLD.id_producto THEN
        RAISE EXCEPTION 'No se puede modificar id_producto';
		
    ELSIF TG_TABLE_NAME = 'Pedido'
       AND NEW.id_pedido <> OLD.id_pedido THEN
        RAISE EXCEPTION 'No se puede modificar id_pedido';
		
    ELSIF TG_TABLE_NAME = 'Linea de pedido'
       AND NEW.id_linea <> OLD.id_linea THEN
        RAISE EXCEPTION 'No se puede modificar id_linea';

    ELSIF TG_TABLE_NAME = 'Trabajador'
       AND NEW.id_trabajador <> OLD.id_trabajador THEN
        RAISE EXCEPTION 'No se puede modificar id_trabajador';

    ELSIF TG_TABLE_NAME = 'Sucursal'
       AND NEW.id_sucursal <> OLD.id_sucursal THEN
        RAISE EXCEPTION 'No se puede modificar id_sucursal';

    ELSIF TG_TABLE_NAME = 'Fabrica'
       AND NEW.id_fabrica <> OLD.id_fabrica THEN
        RAISE EXCEPTION 'No se puede modificar id_fabrica';

    ELSIF TG_TABLE_NAME = 'Almacen'
       AND NEW.id_almacen <> OLD.id_almacen THEN
        RAISE EXCEPTION 'No se puede modificar id_almacen';

    ELSIF TG_TABLE_NAME = 'Modelo'
       AND NEW.id_modelo <> OLD.id_modelo THEN
        RAISE EXCEPTION 'No se puede modificar id_modelo';
    END IF;
		
    RETURN NEW;
END;
$$;


