CREATE FUNCTION public.registrar_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    identificadorL TEXT;
    resumenL TEXT;
BEGIN
    IF TG_OP = 'INSERT' THEN

        IF TG_TABLE_NAME = 'Pedido' THEN
            identificadorL := NEW.id_pedido;
            resumenL := 'Nuevo pedido creado. '
                || 'id_pedido=' || COALESCE(NEW.id_pedido, 'NULL')
                || ', tipo=' || COALESCE(NEW.tipo, 'NULL')
                || ', estado=' || COALESCE(NEW.estado, 'NULL')
                || ', descuento=' || COALESCE(NEW.descuento::TEXT, 'NULL')
                || ', fecha=' || COALESCE(NEW.fecha::TEXT, 'NULL');
        ELSE
            identificadorL := NEW.id_linea;
            resumenL := 'Nueva linea de pedido creada. '
                || 'id_linea=' || COALESCE(NEW.id_linea, 'NULL')
                || ', talla=' || COALESCE(NEW.talla::TEXT, 'NULL')
                || ', cantidad=' || COALESCE(NEW.cantidad::TEXT, 'NULL')
                || ', colorBase=' || COALESCE(NEW."colorBase", 'NULL')
                || ', colorPanel=' || COALESCE(NEW."colorPanel", 'NULL')
                || ', colorSuela=' || COALESCE(NEW."colorSuela", 'NULL')
                || ', colorCordones=' || COALESCE(NEW."colorCordones", 'NULL')
                || ', PrecioTotal=' || COALESCE(NEW."PrecioTotal"::TEXT, 'NULL');
        END IF;

    ELSIF TG_OP = 'UPDATE' THEN

        IF TG_TABLE_NAME = 'Pedido' THEN
            identificadorL := NEW.id_pedido;
            resumenL := 'Pedido modificado. Valores anteriores: '
                || 'id_pedido=' || COALESCE(OLD.id_pedido, 'NULL')
                || ', tipo=' || COALESCE(OLD.tipo, 'NULL')
                || ', estado=' || COALESCE(OLD.estado, 'NULL')
                || ', descuento=' || COALESCE(OLD.descuento::TEXT, 'NULL')
                || ', fecha=' || COALESCE(OLD.fecha::TEXT, 'NULL')
                || ' | Valores nuevos: '
                || 'id_pedido=' || COALESCE(NEW.id_pedido, 'NULL')
                || ', tipo=' || COALESCE(NEW.tipo, 'NULL')
                || ', estado=' || COALESCE(NEW.estado, 'NULL')
                || ', descuento=' || COALESCE(NEW.descuento::TEXT, 'NULL')
                || ', fecha=' || COALESCE(NEW.fecha::TEXT, 'NULL');
        ELSE
            identificadorL := NEW.id_linea;
            resumenL := 'Linea de pedido modificada. Valores anteriores: '
                || 'id_linea=' || COALESCE(OLD.id_linea, 'NULL')
                || ', talla=' || COALESCE(OLD.talla::TEXT, 'NULL')
                || ', cantidad=' || COALESCE(OLD.cantidad::TEXT, 'NULL')
                || ', colorBase=' || COALESCE(OLD."colorBase", 'NULL')
                || ', colorPanel=' || COALESCE(OLD."colorPanel", 'NULL')
                || ', colorSuela=' || COALESCE(OLD."colorSuela", 'NULL')
                || ', colorCordones=' || COALESCE(OLD."colorCordones", 'NULL')
                || ', PrecioTotal=' || COALESCE(OLD."PrecioTotal"::TEXT, 'NULL')
                || ' | Valores nuevos: '
                || 'id_linea=' || COALESCE(NEW.id_linea, 'NULL')
                || ', talla=' || COALESCE(NEW.talla::TEXT, 'NULL')
                || ', cantidad=' || COALESCE(NEW.cantidad::TEXT, 'NULL')
                || ', colorBase=' || COALESCE(NEW."colorBase", 'NULL')
                || ', colorPanel=' || COALESCE(NEW."colorPanel", 'NULL')
                || ', colorSuela=' || COALESCE(NEW."colorSuela", 'NULL')
                || ', colorCordones=' || COALESCE(NEW."colorCordones", 'NULL')
                || ', PrecioTotal=' || COALESCE(NEW."PrecioTotal"::TEXT, 'NULL');
        END IF;

    ELSIF TG_OP = 'DELETE' THEN

        IF TG_TABLE_NAME = 'Pedido' THEN
            identificadorL := OLD.id_pedido;
            resumenL := 'Pedido eliminado. '
                || 'id_pedido=' || COALESCE(OLD.id_pedido, 'NULL')
                || ', tipo=' || COALESCE(OLD.tipo, 'NULL')
                || ', estado=' || COALESCE(OLD.estado, 'NULL')
                || ', descuento=' || COALESCE(OLD.descuento::TEXT, 'NULL')
                || ', fecha=' || COALESCE(OLD.fecha::TEXT, 'NULL');
        ELSE
            identificadorL := OLD.id_linea;
            resumenL := 'Linea de pedido eliminada. '
                || 'id_linea=' || COALESCE(OLD.id_linea, 'NULL')
                || ', talla=' || COALESCE(OLD.talla::TEXT, 'NULL')
                || ', cantidad=' || COALESCE(OLD.cantidad::TEXT, 'NULL')
                || ', colorBase=' || COALESCE(OLD."colorBase", 'NULL')
                || ', colorPanel=' || COALESCE(OLD."colorPanel", 'NULL')
                || ', colorSuela=' || COALESCE(OLD."colorSuela", 'NULL')
                || ', colorCordones=' || COALESCE(OLD."colorCordones", 'NULL')
                || ', PrecioTotal=' || COALESCE(OLD."PrecioTotal"::TEXT, 'NULL');
        END IF;

    END IF;


    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;

END;
$$;


